/* CSS PART 1 OF 2 */

/* DESIGN TOKENS */
:root {
  --ink: #202a30;
  --ink-soft: #536168;
  --navy: #243b48;
  --navy-deep: #192d38;
  --blue: #527889;
  --blue-light: #e8eff1;
  --orange: #d47b43;
  --orange-dark: #b96131;
  --paper: #faf9f6;
  --white: #ffffff;
  --sand: #f0ede6;
  --line: #deddd6;
  --muted: #777e7d;

  --font-display: "Roboto Slab", Georgia, serif;
  --font-body: "DM Sans", Arial, sans-serif;

  --container: 1160px;
  --gutter: 5.5%;
  --radius: 5px;
  --shadow: 0 12px 35px rgba(25, 45, 56, 0.09);
  --transition: 180ms ease;
}

/* RESET */
* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button {
  cursor: pointer;
}

::selection {
  color: var(--white);
  background: var(--blue);
}

/* ACCESSIBILITY */
:focus-visible {
  outline: 3px solid var(--orange);
  outline-offset: 4px;
}

.skip-link {
  position: absolute;
  z-index: 1000;
  top: 12px;
  left: 12px;
  padding: 12px 18px;
  background: var(--white);
  color: var(--ink);
  transform: translateY(-150%);
}

.skip-link:focus {
  transform: translateY(0);
}

/* TYPOGRAPHY */
h1,
h2,
h3,
h4 {
  margin: 0;
  color: var(--navy-deep);
  font-family: var(--font-display);
  font-weight: 600;
  line-height: 1.16;
  letter-spacing: -0.035em;
}

h1 {
  font-size: clamp(2.7rem, 5.8vw, 5.25rem);
}

h2 {
  font-size: clamp(2rem, 3.8vw, 3.25rem);
}

h3 {
  font-size: clamp(1.3rem, 2vw, 1.65rem);
}

p {
  margin: 0 0 1.2rem;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  color: var(--orange-dark);
  font-size: 0.73rem;
  font-weight: 800;
  letter-spacing: 0.15em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 28px;
  height: 2px;
  background: var(--orange);
  content: "";
}

.section-heading {
  max-width: 720px;
  margin-bottom: 22px;
}

.section-intro {
  max-width: 650px;
  color: var(--ink-soft);
  font-size: 1.05rem;
}

.text-accent {
  color: var(--orange-dark);
}

/* SHARED LAYOUT */
.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  padding-block: 108px;
}

.section--white {
  background: var(--white);
}

.section--sand {
  background: var(--sand);
}

.section-header {
  margin-bottom: 48px;
}

.section-header--center {
  margin-inline: auto;
  text-align: center;
}

.section-header--center .eyebrow {
  justify-content: center;
}

.section-header--center .section-intro {
  margin-inline: auto;
}

.split-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 72px;
}

.image-frame {
  position: relative;
  overflow: hidden;
  background: var(--sand);
  border-radius: var(--radius);
}

.image-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 600ms ease;
}

.image-frame:hover img {
  transform: scale(1.025);
}

/* HEADER & NAVIGATION */
.site-header {
  position: sticky;
  z-index: 100;
  top: 0;
  background: var(--white);
  border-bottom: 1px solid rgba(32, 42, 48, 0.09);
}

.header-inner {
  display: flex;
  width: min(1280px, calc(100% - 7%));
  min-height: 88px;
  margin-inline: auto;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
}

.brand {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 13px;
}

.brand-logo {
  width: 64px;
  height: 64px;
  flex: 0 0 auto;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.25;
}

.brand-name {
  color: var(--navy-deep);
  font-family: var(--font-display);
  font-size: 0.98rem;
  font-weight: 700;
}

.brand-description {
  margin-top: 4px;
  color: var(--muted);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.main-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(18px, 2.4vw, 34px);
}

.main-nav a:not(.button) {
  position: relative;
  padding-block: 10px;
  color: var(--ink-soft);
  font-size: 0.85rem;
  font-weight: 700;
  transition: color var(--transition);
}

.main-nav a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: 3px;
  left: 0;
  height: 2px;
  background: var(--orange);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.main-nav a:not(.button):hover {
  color: var(--navy-deep);
}

.main-nav a:not(.button):hover::after {
  transform: scaleX(1);
}

/* BUTTONS */
.button {
  display: inline-flex;
  min-height: 52px;
  padding: 13px 23px;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--orange);
  color: var(--white);
  font-size: 0.85rem;
  font-weight: 800;
  line-height: 1.25;
  text-align: center;
  transition:
    background var(--transition),
    color var(--transition),
    border-color var(--transition),
    transform var(--transition);
}

.button:hover {
  background: var(--orange-dark);
  transform: translateY(-2px);
}

.button--dark {
  background: var(--navy);
}

.button--dark:hover {
  background: var(--navy-deep);
}

.button--outline {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: var(--white);
}

.button--outline:hover {
  border-color: var(--white);
  background: var(--white);
  color: var(--navy-deep);
}

.button--light {
  border-color: var(--line);
  background: var(--white);
  color: var(--navy-deep);
}

.button--light:hover {
  border-color: var(--navy);
  background: var(--navy);
  color: var(--white);
}

/* HERO */
.hero {
  position: relative;
  overflow: hidden;
  background: var(--navy-deep);
  color: var(--white);
}

.hero-inner {
  display: grid;
  width: min(1280px, calc(100% - 7%));
  min-height: 650px;
  margin-inline: auto;
  grid-template-columns: 1.03fr 0.97fr;
  align-items: center;
  gap: 55px;
  padding-block: 78px;
}

.hero-copy {
  position: relative;
  z-index: 2;
  max-width: 660px;
}

.hero .eyebrow {
  color: #efb18a;
}

.hero h1 {
  margin-bottom: 26px;
  color: var(--white);
}

.hero-description {
  max-width: 540px;
  margin-bottom: 32px;
  color: #d6e0e2;
  font-size: clamp(1rem, 1.4vw, 1.13rem);
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 13px;
}

.hero-visual {
  position: relative;
  min-height: 500px;
}

.hero-image {
  position: absolute;
  inset: 0 0 0 25px;
  overflow: hidden;
  border-radius: 3px;
}

.hero-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 45%;
}

.hero-image::after {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    transparent 60%,
    rgba(25, 45, 56, 0.35)
  );
  content: "";
}

.hero-image-accent {
  position: absolute;
  z-index: 1;
  top: 32px;
  left: 0;
  width: 5px;
  height: 115px;
  background: var(--orange);
}

.hero-caption {
  position: absolute;
  z-index: 2;
  right: -18px;
  bottom: 28px;
  max-width: 225px;
  padding: 20px 23px;
  background: var(--white);
  color: var(--navy-deep);
  box-shadow: var(--shadow);
}

.hero-caption strong {
  display: block;
  font-family: var(--font-display);
  font-size: 1.15rem;
}

.hero-caption span {
  display: block;
  margin-top: 5px;
  color: var(--ink-soft);
  font-size: 0.76rem;
}

/* COMPANY DIFFERENTIATORS */
.credentials {
  position: relative;
  z-index: 2;
  background: var(--white);
  border-bottom: 1px solid var(--line);
}

.credentials-inner {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-items: stretch;
}

.credential {
  display: flex;
  min-height: 115px;
  padding: 24px 30px;
  align-items: center;
  gap: 17px;
  border-right: 1px solid var(--line);
}

.credential:first-child {
  border-left: 1px solid var(--line);
}

.credential-number {
  color: var(--orange-dark);
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: 700;
  line-height: 1;
}

.credential-copy strong {
  display: block;
  color: var(--navy-deep);
  font-size: 0.92rem;
}

.credential-copy span {
  color: var(--muted);
  font-size: 0.77rem;
}

/* WHY CHOOSE US */
.why-section {
  background: var(--paper);
}

.why-content {
  max-width: 550px;
}

.why-content h2 {
  margin-bottom: 22px;
}

.why-content > p {
  color: var(--ink-soft);
}

.why-image {
  min-height: 460px;
}

.why-image img {
  object-position: center;
}

.principle-list {
  display: grid;
  margin-top: 32px;
  gap: 0;
}

.principle {
  display: grid;
  padding-block: 19px;
  grid-template-columns: 42px 1fr;
  gap: 15px;
  border-top: 1px solid var(--line);
}

.principle-mark {
  display: flex;
  width: 36px;
  height: 36px;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--blue-light);
  color: var(--navy);
  font-size: 0.95rem;
  font-weight: 800;
}

.principle h3 {
  margin-bottom: 5px;
  font-family: var(--font-body);
  font-size: 0.98rem;
  font-weight: 800;
  letter-spacing: 0;
}

.principle p {
  margin-bottom: 0;
  color: var(--ink-soft);
  font-size: 0.88rem;
}

/* ROOF ATTENTION */
.roof-section {
  background: var(--navy);
  color: var(--white);
}

.roof-section h2,
.roof-section h3 {
  color: var(--white);
}

.roof-section .section-intro {
  color: #d0dcdf;
}

.roof-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: 75px;
}

.roof-copy {
  position: sticky;
  top: 125px;
}

.roof-copy p {
  color: #d0dcdf;
}

.roof-copy .button {
  margin-top: 15px;
}

.roof-signs {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0 30px;
}

.roof-sign {
  padding: 23px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.2);
}

.roof-sign span {
  display: block;
  margin-bottom: 10px;
  color: #efb18a;
  font-family: var(--font-display);
  font-size: 1.35rem;
}

.roof-sign h3 {
  margin-bottom: 8px;
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: 0;
}

.roof-sign p {
  margin-bottom: 0;
  color: #d0dcdf;
  font-size: 0.86rem;
}

/* COLORADO ROOFING PROCESS */
.process-section {
  background: var(--sand);
}

.process-layout {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: center;
  gap: 75px;
}

.process-image {
  min-height: 490px;
}

.process-image img {
  object-position: center 45%;
}

.process-content h2 {
  margin-bottom: 18px;
}

.process-content > p {
  color: var(--ink-soft);
}

.process-steps {
  margin-top: 32px;
  border-top: 1px solid #d7d3ca;
}

.process-step {
  display: grid;
  padding: 20px 0;
  grid-template-columns: 46px 1fr;
  gap: 16px;
  border-bottom: 1px solid #d7d3ca;
}

.process-step-number {
  color: var(--orange-dark);
  font-family: var(--font-display);
  font-size: 1.45rem;
  font-weight: 700;
}

.process-step h3 {
  margin-bottom: 5px;
  font-family: var(--font-body);
  font-size: 0.97rem;
  font-weight: 800;
  letter-spacing: 0;
}

.process-step p {
  margin-bottom: 0;
  color: var(--ink-soft);
  font-size: 0.87rem;
}

/* RECENT PROJECTS */
.projects-section {
  background: var(--white);
}

.projects-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
}

.project {
  min-width: 0;
}

.project--featured {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  align-items: stretch;
  background: var(--paper);
}

.project-image {
  min-height: 280px;
  overflow: hidden;
  background: var(--sand);
}

.project--featured .project-image {
  min-height: 430px;
}

.project-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 500ms ease;
}

.project:hover .project-image img {
  transform: scale(1.035);
}

.project-details {
  padding: 28px;
}

.project--featured .project-details {
  display: flex;
  padding: clamp(28px, 5vw, 65px);
  flex-direction: column;
  justify-content: center;
}

.project-type {
  display: inline-block;
  margin-bottom: 12px;
  color: var(--orange-dark);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.project-details h3 {
  margin-bottom: 10px;
}

.project-details p {
  margin-bottom: 0;
  color: var(--ink-soft);
  font-size: 0.9rem;
}

.project--standard {
  border-bottom: 1px solid var(--line);
}

.project--standard .project-image {
  height: 320px;
}

.project--standard .project-details {
  padding: 23px 0 28px;
}

/* INTERACTION STATES */
a,
button {
  -webkit-tap-highlight-color: transparent;
}

a:hover {
  text-decoration: none;
}

.button:active {
  transform: translateY(0);
}
```

